data.script:
function check(v,m){if(!v)throw new Error(m);}
const g=ActionGroup.find('QA Empty café 🐼');
check(g && g.uuid==='BBBF0003-0000-4000-8000-000000000011' && g.actions.length===0,'empty installed group');
const url=g.installURL;
const payload=JSON.parse(decodeURIComponent(url.split('data=')[1]));
check(payload.actions.length===0 && payload.actionGroups.length===1,'empty envelope');
const record=payload.actionGroups[0];
check(record.id===g.uuid && record.name===g.name && record.symbol==='folder.fill' && record.order===7,'group record');
check(url===g.installURL,'stable URL');
editor.setText('Empty group link passed café 🐼\n'+url);draft.update();
